      const frames = h.frames();
      expect({tail: frames.slice(-4), errors: frames.filter(frame => frame.startsWith('error'))}).toEqual({
        tail: ['upsert 2 assistant ""', `delta 2 ${JSON.stringify(SENTENCE)}`, 'commit 2', 'stream_end'],
